# %% ../nbs/02_check.ipynb #c006
CHROME = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'

def chrome_path():
    "The Chrome to use, or None for playwright's own Chromium."
    p = os.getenv('RUPAKA_CHROME') or CHROME
    return p if Path(p).exists() else None

@contextmanager
def browser():
    "A headless browser for `check`, closed at the end."
    from playwright.sync_api import sync_playwright
    with sync_playwright() as pw:
        b = pw.chromium.launch(executable_path=chrome_path(), headless=True)
        try: yield b
        finally: b.close()

# %% ../nbs/02_check.ipynb #c008
def _loop_running():
    try: asyncio.get_running_loop(); return True
    except RuntimeError: return False

def in_thread(f, *a, **kw):
    "Call `f`; in a thread when an asyncio loop runs here (as in a notebook), because playwright's sync API cannot run in a loop."
    if not _loop_running(): return f(*a, **kw)
    with ThreadPoolExecutor(1) as ex: return ex.submit(f, *a, **kw).result()

def _starts():
    with browser(): return True

@functools.cache
def can_check() -> bool:
    "True when playwright and a browser are there."
    try: return in_thread(_starts)
    except Exception: return False

